constraints:
1 ≤ N ≤ 10^{3}
1 ≤ Arr[i] ≤ 10^{3}
1 ≤ L ≤ R ≤ 10^{9}

expected time complexity: O(N^{2})
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def countTriplets(self, Arr, N, L, R):
		Arr.sort()
		n = len(Arr)
		a = 0
		b = 0
		for i in range(n - 2):
			j = i + 1
			k = n - 1
			while j < k:
				if Arr[i] + Arr[j] + Arr[k] <= R:
					a += k - j
					j += 1
				else:
					k -= 1
		for i in range(n - 2):
			j = i + 1
			k = n - 1
			while j < k:
				if Arr[i] + Arr[j] + Arr[k] <= L - 1:
					b += k - j
					j += 1
				else:
					k -= 1
		return a - b
